    public static void Configure(ModelBuilder modelBuilder)
    {
        var communitiesByName = CommunitySeeds.ToDictionary(x => x.Name);

        modelBuilder.Entity<Customer>().HasData(CustomerSeeds);

        // Repeated codes represent one meter; the first source row determines its customer.
        modelBuilder.Entity<MeteringPoint>().HasData(
            MeterSeeds
                .Select(seed => seed.MeteringPoint)
                .DistinctBy(x => x.MeteringPointCode));

        modelBuilder.Entity<EnergyCommunity>().HasData(CommunitySeeds);

        modelBuilder.Entity<CommunityParticipation>().HasData(
            MeterSeeds
                .DistinctBy(x => (x.MeteringPoint.MeteringPointCode, x.CommunityName))
                .Select(seed => new CommunityParticipation
                {
                    Id = CreateId("participation", $"{seed.MeteringPoint.MeteringPointCode}|{seed.CommunityName}"),
                    EnergyCommunityId = communitiesByName[seed.CommunityName].Id,
                    MeteringPointId = seed.MeteringPoint.Id,
                    ParticipationPercentage = 100,
                    CreatedAtUtc = SeededAtUtc
                }));
    }

    // HasData requires primary keys to remain stable across model builds.
    private static Guid CreateId(string entityType, string key)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes($"{entityType}:{key}"));
        return new Guid(hash.AsSpan(0, 16));
    }

    private sealed record MeterSeed(MeteringPoint MeteringPoint, string CommunityName);
}
